import sys
import heapq

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    idx = 0
    N = data[idx]
    M = data[idx + 1]
    K = data[idx + 2]
    idx += 3

    P = [0] * (K + 1)
    for i in range(1, K + 1):
        P[i] = data[idx]
        idx += 1

    edges_by = [[] for _ in range(K + 1)]
    for _ in range(M):
        v = data[idx] - 1
        u = data[idx + 1] - 1
        t = data[idx + 2]
        idx += 3
        edges_by[t].append((v, u))

    A = data[idx] - 1
    B = data[idx + 1] - 1
    del data

    station_edges = [[] for _ in range(N)]
    comp_members = []
    comp_price = []

    for t in range(1, K + 1):
        edges = edges_by[t]
        if not edges:
            continue

        local = {}
        for u, v in edges:
            if u in local:
                local[u].append(v)
            else:
                local[u] = [v]
            if v in local:
                local[v].append(u)
            else:
                local[v] = [u]

        visited = set()
        price = P[t]

        for start in local:
            if start in visited:
                continue

            stack = [start]
            visited.add(start)
            comp = []

            while stack:
                x = stack.pop()
                comp.append(x)
                for y in local[x]:
                    if y not in visited:
                        visited.add(y)
                        stack.append(y)

            cid = N + len(comp_members)
            comp_members.append(comp)
            comp_price.append(price)

            for x in comp:
                station_edges[x].append(cid)

        edges_by[t] = None
        del edges, local, visited

    del edges_by, P

    INF = 10**18
    total_nodes = N + len(comp_members)
    dist = [INF] * total_nodes
    dist[A] = 0

    pq = [(0, A)]

    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        if u == B:
            break

        if u < N:
            for cid in station_edges[u]:
                nd = d + comp_price[cid - N]
                if nd < dist[cid]:
                    dist[cid] = nd
                    heapq.heappush(pq, (nd, cid))
        else:
            comp_idx = u - N
            for v in comp_members[comp_idx]:
                if d < dist[v]:
                    dist[v] = d
                    heapq.heappush(pq, (d, v))

    ans = dist[B]
    print(-1 if ans == INF else ans)

if __name__ == "__main__":
    solve()
